js-easy2-error-first-callback.alternative:
const safeDivide = (a, b, callback) => {
  if (b === 0) {
    callback(new Error("Cannot divide by zero"));
    // Return here, or the success call below would run as well.
    return;
  }
  callback(null, a / b);
};

js-easy2-after-n-calls.alternative:
const after = (count, done) => {
  let calls = 0;
  return () => {
    calls += 1;
    // === rather than >=, so done fires on the count-th call only.
    if (calls === count) done();
  };
};

